,cheatday_kcal_readout_title:778,cheatday_kcal_readout_main:779,cheatday_kcal_readout_plus:780,cheatday_kcal_readout_per:781,cheatday_kcal_readout_no_deficit:782,cheatday_kcal_readout_crashout:783,cheatday_kcal_banner_line:784,cheatday_sacrifice_foot:785,cheatday_activated_with_kcal:786,edit_goals_advanced:787,goals_auto_note:788,formula_info:789,formula_current_masses:790,formula_maintenance:791,formula_macro_title:792,formula_macro_protein:793,formula_macro_fat:794,formula_macro_carbs:795,formula_kcal_title:796,formula_kcal_everyday:797,formula_kcal_cut_prefix:798,formula_kcal_cut_suffix:799,formula_kcal_cut_current:800,formula_kcal_bulk:801,formula_kcal_hint:802,goals_dialog_title:803,day_note:804,no_note:805,edit_note:806,note_hint:807,meal_note:808,meal_note_hint:809,meal_note_checklist_sub:810,meal_note_add_line:811,meal_note_line_hint:812,meal_note_remove_line:813,meal_expand_inline:814,meal_open_tracked:815,meal_add_menu:816,meal_tracked_popup_title:817,meal_tracked_empty:818,track_edit_mode_g:819,track_edit_mode_kcal:820,track_edit_portion_hint:821,track_portion_manual_title:822,track_mode_short_protein:823,track_mode_short_carbs:824,track_mode_short_fat:825,track_edit_grams_only:826,meal_compact_gestures_hint:827,alltag_distribution:828,alltag_performance:829,alltag_relaxed:830,alltag_distribution_hint:831,alltag_kcal_change_label:832,alltag_apply:833,alltag_applied_msg:834,meal_order_title:835,meal_order_hint:836,meal_order_free_hint:837,meal_order_free_sub:838,meal_order_rename:839,meal_rename_title:840,meal_rename_label:841,meal_order_block_hint:842,meal_order_snacks_locked:843,commitment_title:844,commitment_body:845,commitment_quote:846,commitment_checkbox:847,commitment_confirm:848,commitment_decline:849,mode_aggressive_badge:850,mode_aggressive_sub:851,activity_level_title:852,activity_level_hint:853,activity_level_very_active:854,activity_level_normal:855,activity_level_low:856,formula_activity_line:857,cut_movement_block_title:858,cut_movement_blo